`,s.jsxs(e.p,{children:["Because both arrow families are derivatives of one traveling shape ",s.jsxs(e.span,{className:"katex",children:[s.jsx(e.span,{className:"katex-mathml",children:s.jsx(e.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:s.jsxs(e.semantics,{children:[s.jsxs(e.mrow,{children:[s.jsx(e.mi,{children:"f"}),s.jsx(e.mo,{stretchy:"false",children:"("}),s.jsx(e.mi,{children:"x"}),s.jsx(e.mo,{children:"−"}),s.jsx(e.mi,{children:"c"}),s.jsx(e.mi,{children:"t"}),s.jsx(e.mo,{stretchy:"false",children:")"})]}),s.jsx(e.annotation,{encoding:"application/x-tex",children:"f(x - ct)"})]})})}),s.jsxs(e.span,{className:"katex-html","aria-hidden":"true",children:[s.jsxs(e.span,{className:"base",children:[s.jsx(e.span,{className:"strut",style:{height:"1em",verticalAlign:"-0.25em"}}),s.jsx(e.span,{className:"mord mathnormal",style:{marginRight:"0.1076em"},children:"f"}),s.jsx(e.span,{className:"mopen",children:"("}),s.jsx(e.span,{className:"mord mathnormal",children:"x"}),s.jsx(e.span,{className:"mspace",style:{marginRight:"0.2222em"}}),s.jsx(e.span,{className:"mbin",children:"−"}),s.jsx(e.span,{className:"mspace",style:{marginRight:"0.2222em"}})]}),s.jsxs(e.span,{className:"base",children:[s.jsx(e.span,{className:"strut",style:{height:"1em",verticalAlign:"-0.25em"}}),s.jsx(e.span,{className:"mord mathnormal",children:"c"}),s.jsx(e.span,{className:"mord mathnormal",children:"t"}),s.jsx(e.span,{className:"mclose",children:")"})]})]})]}),`, they
